(* ============================================================
   TYPE CORRESPONDENCE TABLE
   ============================================================ *)

(*
   HOL Type              Lean Type              Agda Type
   --------              ---------              ---------
   bool                  Bool                   Bool
   nat                   Nat                    ℕ
   int                   Int                    ℤ
   real                  ℝ                      ℝ
   'a list               List α                 List α
   'a * 'b               α × β                  α × β
   'a option             Option α               Maybe α
   graph                 Graph                  Graph
   system_state          SystemState            SystemState
   canonical_structure   CanonicalStructure     CanonicalStructure
   component             Component              Component

   Quantifiers:
   !x.P                  ∀ x, P x              ∀ x → P x
   ?x.P                  ∃ x, P x              ∃ x × P x

   Logical Operators:
   P ∧ Q                 P ∧ Q                 P ∧ Q
   P ∨ Q                 P ∨ Q                 P ∨ Q
   ~P                    ¬P                     ¬ P
   P ⟹ Q                 P → Q                 P → Q
   P ↔ Q                 P ↔ Q                 P ↔ Q
*)

(* ============================================================
   CONSTRAINT KIND MAPPING
   ============================================================ *)

type hol_constraint_kind =
  | Prohibition
  | Technology
  | BooleanAlgebra
  | RefinementType
  | GraphInvariant
  | OrderInvariant
  | EquivalenceClass
;;

let constraint_kind_to_lean : hol_constraint_kind -> string = function
  | Prohibition -> "ConstraintKind.Prohibition"
  | Technology -> "ConstraintKind.Technology"
  | BooleanAlgebra -> "ConstraintKind.BooleanAlgebra"
  | RefinementType -> "ConstraintKind.RefinementType"
  | GraphInvariant -> "ConstraintKind.GraphInvariant"
  | OrderInvariant -> "ConstraintKind.OrderInvariant"
  | EquivalenceClass -> "ConstraintKind.EquivalenceClass"
;;

let constraint_kind_to_agda : hol_constraint_kind -> string = function
  | Prohibition -> "ConstraintKind.prohibition"
  | Technology -> "ConstraintKind.technology"
  | BooleanAlgebra -> "ConstraintKind.boolean-algebra"
  | RefinementType -> "ConstraintKind.refinement-type"
  | GraphInvariant -> "ConstraintKind.graph-invariant"
  | OrderInvariant -> "ConstraintKind.order-invariant"
  | EquivalenceClass -> "ConstraintKind.equivalence-class"
;;

(* ============================================================
   POLARITY MAPPING
   ============================================================ *)

type hol_polarity =
  | Positive
  | Negative
  | Neutral
;;

let polarity_to_lean : hol_polarity -> string = function
  | Positive -> "Polarity.Positive"
  | Negative -> "Polarity.Negative"
  | Neutral -> "Polarity.Neutral"
;;

let polarity_to_agda : hol_polarity -> string = function
  | Positive -> "polarity-positive"
  | Negative -> "polarity-negative"
  | Neutral -> "polarity-neutral"
;;

