(*
 * Proof templates for cross-prover correspondence.
 * Each template shows the structure of a correspondence proof,
 * indicating what must be proven to establish semantic equivalence.
 *)

let correspondence_proof_templates : (string * string) list = [
  ("template-boolean-equivalence",
   {|Lean proof that HOL boolean obligation ⟺ Lean boolean obligation:

     theorem hol_lean_bool_equiv (p q : Prop) :
       (HOL.of_lean (p ∧ q)) = (HyperKitty.and p q) := by
         rfl  -- Assumes identity semantics
   |});

  ("template-graph-preservation",
   {|Lean proof that graph operations preserve structure:

     theorem hol_lean_graph_equiv (g : Graph) :
       (HOL.acyclic_of g) = (HyperKitty.isAcyclic g) := by
         cases g
         simp [HOL.acyclic_of, HyperKitty.isAcyclic]
   |});

  ("template-predicate-strengthening",
   {|Lean proof that refined predicates maintain refinement order:

     theorem hol_lean_refine_equiv (P Q : α → Prop) :
       (HOL.refines P Q) = (HyperKitty.refines P Q) := by
         unfold HOL.refines HyperKitty.refines
         simp [implies_iff_right]
   |});

  ("template-agda-verification",
   {|Agda proof that Lean correspondence corresponds to Agda:

     agda-correspondence : ∀ {p q : Set} →
       (Lean.of_agda (p ∧ q)) ≡ (HyperKitty.and p q)
     agda-correspondence = λ p q → refl
   |});
];;

